1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; padding: 2rem 1rem; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 32rem; margin: 0 auto; }
11	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
12	  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
13	  input { flex: 1; padding: .5rem .75rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: .5rem .9rem; font: inherit; border: 1px solid #bbb; border-radius: 6px; background: #fff; cursor: pointer; }
15	  button:hover { background: #eee; }
16	  ul { list-style: none; margin: 0; padding: 0; }
17	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem .75rem; margin-bottom: .4rem; background: #fff; border: 1px solid #e2e2e2; border-radius: 6px; }
18	  li span { flex: 1; overflow-wrap: anywhere; }
19	</style>
20	</head>
21	<body>
22	<main>
23	  <h1>Todos</h1>
24	  <form id="todo-form">
25	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
26	    <button data-testid="todo-add" type="submit">Add</button>
27	  </form>
28	  <ul data-testid="todo-list"></ul>
29	</main>
30	<script>
31	  var STORAGE_KEY = 'todos';
32	  var form = document.getElementById('todo-form');
33	  var input = document.querySelector('[data-testid="todo-input"]');
34	  var list = document.querySelector('[data-testid="todo-list"]');
35	
36	  // [REQ-001] Load todos from localStorage; ignore malformed data.
37	  function loadTodos() {
38	    try {
39	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
40	      return Array.isArray(parsed) ? parsed : [];
41	    } catch (e) {
42	      return [];
43	    }
44	  }
45	
46	  // [REQ-001]
47	  function saveTodos() {
48	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
49	  }
50	
51	  // [REQ-001] Stable unique id; crypto.randomUUID is not available in every file:// context.
52	  function makeId() {
53	    if (window.crypto && typeof crypto.randomUUID === 'function') {
54	      try { return crypto.randomUUID(); } catch (e) {}
55	    }
56	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
57	  }
58	
59	  // [REQ-001]
60	  function render() {
61	    list.textContent = '';
62	    todos.forEach(function (todo) {
63	      var li = document.createElement('li');
64	      li.setAttribute('data-testid', 'todo-item');
65	      li.dataset.id = todo.id;
66	
67	      var text = document.createElement('span');
68	      text.setAttribute('data-testid', 'todo-text');
69	      text.textContent = todo.text;
70	
71	      var del = document.createElement('button');
72	      del.type = 'button';
73	      del.setAttribute('data-testid', 'todo-delete');
74	      del.textContent = 'Delete';
75	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
76	      del.addEventListener('click', function () { deleteTodo(todo.id); });
77	
78	      li.appendChild(text);
79	      li.appendChild(del);
80	      list.appendChild(li);
81	    });
82	  }
83	
84	  // [REQ-001]
85	  function addTodo(rawText) {
86	    var text = rawText.trim();
87	    if (!text) return;
88	    todos.push({ id: makeId(), text: text, createdAt: Date.now() });
89	    saveTodos();
90	    render();
91	  }
92	
93	  // [REQ-001]
94	  function deleteTodo(id) {
95	    todos = todos.filter(function (t) { return t.id !== id; });
96	    saveTodos();
97	    render();
98	  }
99	
100	  var todos = loadTodos();
101	
102	  form.addEventListener('submit', function (e) {
103	    e.preventDefault();
104	    addTodo(input.value);
105	    input.value = '';
106	    input.focus();
107	  });
108	
109	  render();
110	</script>
111	</body>
112	</html>
